public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());

        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());

        long[] positions = new long[n];
        for (int i = 0; i < n; i++) {
            positions[i] = Long.parseLong(br.readLine());
        }

        if (k == 0) {
            System.out.println(0);
            return;
        }

        // Calculate distances
        long[] distances = new long[n - 1];
        for (int i = 0; i < n - 1; i++) {
            distances[i] = positions[i + 1] - positions[i];
        }

        // Priority queue approach
        PriorityQueue<Node> pq = new PriorityQueue<>();
        boolean[] used = new boolean[distances.length];

        for (int i = 0; i < distances.length; i++) {
            pq.offer(new Node(distances[i], i));
        }

        long total = 0;
        int count = 0;

        while (count < k && !pq.isEmpty()) {
            Node node = pq.poll();
            int idx = node.idx;

            if (used[idx]) continue;

            used[idx] = true;
            total += node.cost;
            count++;

            // Mark neighbors as potentially mergeable
            if (idx > 0) used[idx - 1] = true;
            if (idx < distances.length - 1) used[idx + 1] = true;
        }

        System.out.println(total);
    }

    static class Node implements Comparable<Node> {
        long cost;
        int idx;

        Node(long cost, int idx) {
            this.cost = cost;
            this.idx = idx;
        }

        public int compareTo(Node other) {
            return Long.compare(this.cost, other.cost);
        }
    }
}

