def sieve(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i*i, n + 1, i):
                is_prime[j] = False

    return [i for i in range(2, n + 1) if is_prime[i]]

def goldbach(n, primes, is_prime):
    """Find two primes that sum to n"""
    for p in primes:
        if p > n:
            break
        if is_prime[n - p]:
            return p, n - p
    return None, None

