import java.util.*;
import java.io.*;

public class Main {
    static Map<Integer, List<Integer>> graph = new HashMap<>();
    static Map<Integer, Integer> color = new HashMap<>();
    static boolean isBipartite = true;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());

        List<int[]> edges = new ArrayList<>();

        while (true) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());

            if (a == -1 && b == -1) break;

            edges.add(new int[]{a, b});
            graph.putIfAbsent(a, new ArrayList<>());
            graph.putIfAbsent(b, new ArrayList<>());
            graph.get(a).add(b);
            graph.get(b).add(a);
        }

        if (edges.isEmpty()) {
            System.out.println(0);
            return;
        }

        for (int node : graph.keySet()) {
            if (!color.containsKey(node)) {
                bfs(node);
            }
        }

        if (!isBipartite) {
            System.out.println(0);
        } else {
            System.out.println(1);

            List<Integer> team1 = new ArrayList<>();
            List<Integer> team2 = new ArrayList<>();

            for (Map.Entry<Integer, Integer> entry : color.entrySet()) {
                if (entry.getValue() == 0) {
                    team1.add(entry.getKey());
                } else {
                    team2.add(entry.getKey());
                }
            }

            Collections.sort(team1);
            Collections.sort(team2);

            for (int x : team1) System.out.print(x + " ");
            System.out.println("-1");

            for (int x : team2) System.out.print(x + " ");
            System.out.println("-1");
        }
    }

    static void bfs(int start) {
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(start);
        color.put(start, 0);

        while (!queue.isEmpty()) {
            int node = queue.poll();

            for (int neighbor : graph.get(node)) {
                if (!color.containsKey(neighbor)) {
                    color.put(neighbor, 1 - color.get(node));
                    queue.offer(neighbor);
                } else if (color.get(neighbor).equals(color.get(node))) {
                    isBipartite = false;
                    return;
                }
            }
        }
    }
}

