map<int, vector<int>> graph;
map<int, int> color;
bool isBipartite = true;

void bfs(int start) {
    queue<int> q;
    q.push(start);
    color[start] = 0;

    while (!q.empty()) {
        int node = q.front();
        q.pop();

        for (int neighbor : graph[node]) {
            if (color.find(neighbor) == color.end()) {
                color[neighbor] = 1 - color[node];
                q.push(neighbor);
            } else if (color[neighbor] == color[node]) {
                isBipartite = false;
                return;
            }
        }
    }
}

